-- ===========================================================================
-- Puntos de control - GRASP v2 (resumen divulgativo)
-- ===========================================================================

INSERT INTO control_points (chapter_id, ref, title, description, level, guidance, evidence_examples, applicable_scopes, sort_order)
SELECT ch.id, cp.ref, cp.title, cp.description, cp.level, cp.guidance, cp.evidence_examples, cp.scopes, cp.sort_order
FROM audit_standards s
JOIN standard_chapters ch ON ch.standard_id = s.id
JOIN (VALUES
 ('REP','G 1.1','Representante de los trabajadores elegido','Existe al menos un representante o comité de los trabajadores, elegido libremente por ellos y reconocido por la dirección.','MAJOR_MUST','El representante trata cuestiones de bienestar y actúa de interlocutor con la dirección. Acta de elección disponible.','Acta de elección; datos de contacto del representante','ALL',1),
 ('REP','G 1.2','Reuniones y diálogo documentado','Se celebran reuniones periódicas entre el representante de los trabajadores y la dirección y se registran los temas tratados.','RECOMMENDATION','Frecuencia razonable (p. ej. trimestral) y actas accesibles.','Actas de reunión','ALL',2),
 ('COMP','G 2.1','Procedimiento de quejas accesible','Hay un procedimiento de quejas por escrito, comunicado a los trabajadores, que permite presentar reclamaciones de forma confidencial.','MAJOR_MUST','Incluye plazos de respuesta y garantía de no represalia.','Procedimiento de quejas; cartel informativo; buzón','ALL',1),
 ('COMP','G 2.2','Registro y seguimiento de quejas','Las quejas recibidas se registran junto con la investigación, la resolución y los plazos.','RECOMMENDATION','Registro con fecha de entrada, descripción y cierre.','Registro de quejas','ALL',2),
 ('SELFDECL','G 3.1','Autodeclaración de buenas prácticas sociales','La dirección ha firmado una autodeclaración que compromete a la empresa con las buenas prácticas sociales y su comunicación a los trabajadores.','MAJOR_MUST','Debe estar firmada, fechada, visible y renovarse periódicamente.','Autodeclaración firmada y expuesta','ALL',1),
 ('SELFDECL','G 3.2','Persona responsable de recursos humanos designada','Se ha designado a una persona responsable de la implantación de las buenas prácticas sociales y del cumplimiento de la legislación laboral.','MAJOR_MUST','Nombre y funciones documentados; conoce la legislación aplicable.','Designación por escrito; descripción de funciones','ALL',2),
 ('CHILD','G 4.1','Cumplimiento de la edad mínima de trabajo','No se emplea a menores por debajo de la edad mínima legal o de 15 años (la que sea mayor); se conservan copias de documentos de identidad.','MAJOR_MUST','Convenios OIT nº 138 y 182. Verificar edad en la contratación.','Copias de DNI/pasaporte; registro de personal con fecha de nacimiento','ALL',1),
 ('CHILD','G 4.2','Protección de los trabajadores jóvenes','Los trabajadores jóvenes (por debajo de 18) no realizan trabajos peligrosos ni nocturnos y su jornada respeta la escolarización.','MAJOR_MUST','Evaluación específica de riesgos para menores de 18.','Lista de trabajadores jóvenes; asignación de tareas','ALL',2),
 ('CHILD','G 4.3','Acceso a educación de los hijos de trabajadores en el sitio','Los hijos de los trabajadores que viven o acompañan en la explotación tienen acceso a la escolarización obligatoria.','RECOMMENDATION','Especialmente relevante con trabajadores migrantes o temporeros alojados.','Acuerdos con centros escolares; transporte escolar','ALL',3),
 ('CONTRACT','G 5.1','Contratos de trabajo por escrito','Todos los trabajadores tienen un contrato o acuerdo escrito comprensible que incluye tareas, jornada, salario y periodo de pago.','MAJOR_MUST','En un idioma que el trabajador entienda; una copia se entrega al trabajador.','Modelos de contrato; muestra de contratos firmados','ALL',1),
 ('CONTRACT','G 5.2','Registro de horas trabajadas','Se lleva un registro fiable de las horas de trabajo de cada trabajador, incluidas las horas extraordinarias.','MAJOR_MUST','Fichajes, partes de trabajo o sistema equivalente conservados.','Registros horarios; hojas de fichaje','ALL',2),
 ('CONTRACT','G 5.3','Acceso de los trabajadores a su documentación','Los trabajadores pueden acceder a sus contratos, nóminas y registros de horas.','RECOMMENDATION','Entrega de copias o acceso a solicitud.','Acuse de recibo de nóminas','ALL',3),
 ('WAGES','G 6.1','Pago de al menos el salario mínimo','La retribución es igual o superior al salario mínimo legal o de convenio aplicable, incluido el trabajo a destajo.','MAJOR_MUST','El destajo debe permitir alcanzar el mínimo en jornada normal. Convenio OIT nº 100.','Nóminas; tablas salariales del convenio; cálculo del destajo','ALL',1),
 ('WAGES','G 6.2','Pago regular y comprensible','El salario se abona con regularidad, por medios trazables y con una nómina que el trabajador puede entender.','MAJOR_MUST','Sin deducciones no autorizadas ni retrasos injustificados.','Nóminas; justificantes de transferencia','ALL',2),
 ('HOURS','G 7.1','Jornada conforme a la legislación','La jornada laboral y las horas extraordinarias respetan los límites legales y las horas extra son voluntarias y se pagan.','MAJOR_MUST','Comparar registros de horas con los límites legales del país.','Registros de horas; recibos de horas extra','ALL',1),
 ('HOURS','G 7.2','Descanso semanal','Los trabajadores disfrutan de al menos un día de descanso cada siete días, salvo excepciones legales pactadas.','RECOMMENDATION','Excepciones documentadas y compensadas.','Cuadrantes de turnos','ALL',2),
 ('NONDISC','G 8.1','No discriminación','No hay discriminación en la contratación, retribución, formación, promoción o despido por motivos protegidos.','MAJOR_MUST','Convenio OIT nº 111. Política de igualdad comunicada.','Política de no discriminación; datos de plantilla','ALL',1),
 ('NONDISC','G 8.2','Libertad de asociación','Los trabajadores son libres de afiliarse a organizaciones de su elección y de negociar colectivamente sin represalias.','MAJOR_MUST','Convenios OIT nº 87 y 98. Donde la ley lo restrinja, se permiten medios paralelos de asociación.','Declaración de la dirección; ausencia de casos de represalia','ALL',2)
) AS cp(chapter_code, ref, title, description, level, guidance, evidence_examples, scopes, sort_order)
  ON cp.chapter_code = ch.code
WHERE s.code = 'GRASP_V2';
